INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','linking-clauses','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"linking-clauses","title":"Linking clauses: time, reason, purpose and result","level":"B1","order":45,"summary":"Connect ideas with the right kind of clause or phrase, and keep their logical relationship clear.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Coordinating complete ideas","Reasons: because and because of","Purpose and result","Time clauses and sequence"],"rules":[{"title":"Coordinating complete ideas","explanation":"And, but and or can connect words, phrases or clauses of equal status. When linking two independent clauses, punctuation helps mark the boundary. Choose the connector from the intended relation: addition, contrast or alternative.","pattern":"We checked the route, **and** we booked the tickets.","commonMistakes":["A connector should express the intended relation; grammatical sentences can still communicate the wrong logic."],"examples":["“We were tired **because** we had prepared the visitor guide all morning.”","“We were tired **because** we had restored the old portrait all morning.”"],"skill":"form"},{"title":"Reasons: because and because of","explanation":"Because introduces a finite clause with a subject and verb. Because of introduces a noun phrase or an -ing expression. The meaning may be similar, but the grammar following the connector differs.","pattern":"**Because it rained**, we stayed. / **Because of the rain**, we stayed.","commonMistakes":["Because of it rained puts a finite clause after a preposition phrase without the structure needed for it."],"examples":["“We could not prepare the visitor guide **because of** the power cut.”","“We could not restore the old portrait **because of** the power cut.”"],"skill":"meaning"},{"title":"Purpose and result","explanation":"A to-infinitive often gives purpose when its understood subject matches the main subject. So that can introduce a finite purpose clause, especially when the subjects differ. So and therefore can introduce results, but therefore behaves as an adverb and needs suitable sentence punctuation.","pattern":"I spoke slowly **so that everyone could follow**.","commonMistakes":["Therefore cannot always replace so between two clauses with the same punctuation; avoid a comma splice."],"examples":["Express purpose with a different subject: “I brought the instructions **so that** you could prepare the visitor guide.”","Express purpose with a different subject: “I brought the instructions **so that** you could restore the old portrait.”"],"skill":"contrast"},{"title":"Time clauses and sequence","explanation":"When, while, before, after, until and as soon as describe different temporal relations. While often accompanies an activity in progress; until describes continuation up to a point. In an ordinary future time clause, use a present form rather than will.","pattern":"I’ll wait **until you arrive**.","commonMistakes":["By Friday gives a deadline; until Friday says something continues to Friday. They are not interchangeable."],"examples":["Use the time preposition before an -ing noun phrase: “The error occurred during the process of **preparing** the visitor guide.”","Use the time preposition before an -ing noun phrase: “The error occurred during the process of **restoring** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"2351de95-e8ba-55e7-a969-d2c478086fa2","topicSlug":"linking-clauses","level":"B1","prompt":"“We were tired ____ we had prepared the visitor guide all morning.”","choices":[{"id":"A","text":"despite"},{"id":"B","text":"during"},{"id":"C","text":"because"},{"id":"D","text":"because of"}],"answerId":"C","hint":"The reason has its own **subject and verb**.","explanation":"**Because** introduces the reason as a finite clause: we had ... .","keywords":["because-finite-clause"],"skill":"because-finite-clause","contextKey":"linking-clauses-1","fingerprint":"73369250a1f7505c8c054e085dc9e98b3d56cd16bf14b5d1701e0369bb8c856e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reason has its own **subject and verb**.","**Because** introduces the reason as a finite clause: we had ... .","Choose **because**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Despite would need a noun phrase and would express contrast, not the stated reason.","B":"During takes a noun phrase, not a finite clause.","C":"**Because** introduces the reason as a finite clause: we had ... .","D":"Because of normally takes a noun phrase or -ing expression, not this finite clause."}}},{"id":"c6c37b3e-43e0-5b4d-a5d7-cf59ff1d6f2c","topicSlug":"linking-clauses","level":"B1","prompt":"“We could not prepare the visitor guide ____ the power cut.”","choices":[{"id":"A","text":"while"},{"id":"B","text":"because of"},{"id":"C","text":"because"},{"id":"D","text":"although"}],"answerId":"B","hint":"The reason is a **noun phrase**, so choose because of.","explanation":"The reason is a noun phrase, **the power cut**, so use **because of**.","keywords":["because-of-noun"],"skill":"because-of-noun","contextKey":"linking-clauses-1","fingerprint":"0e5948ccbdc67eb50210deb9930b493b6083ff33f633c3abccf52b55f66287eb","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reason is a **noun phrase**, so choose because of.","The reason is a noun phrase, **the power cut**, so use **because of**.","Choose **because of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"While would normally introduce a clause, not this bare reason phrase.","B":"The reason is a noun phrase, **the power cut**, so use **because of**.","C":"Because requires a finite reason clause rather than this noun phrase alone.","D":"Although normally introduces a finite clause and gives contrast rather than this reason."}}},{"id":"8f35ae6c-bc1b-5caa-a7e6-b769cc915135","topicSlug":"linking-clauses","level":"B1","prompt":"Express purpose with a different subject: “I brought the instructions ____ you could prepare the visitor guide.”","choices":[{"id":"A","text":"in order to"},{"id":"B","text":"because of"},{"id":"C","text":"despite"},{"id":"D","text":"so that"}],"answerId":"D","hint":"The purpose clause has its own subject **you** and modal **could**.","explanation":"**So that** introduces a finite purpose clause whose subject is you.","keywords":["purpose-so-that"],"skill":"purpose-so-that","contextKey":"linking-clauses-1","fingerprint":"ad8500e6a5b654a992f29622bf2949a1a2c5db61a11ba397c28123c0b02fcf28","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The purpose clause has its own subject **you** and modal **could**.","**So that** introduces a finite purpose clause whose subject is you.","Choose **so that**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In order to needs a base verb immediately, not you could.","B":"Because of cannot introduce this finite purpose clause.","C":"Despite both changes the relation and requires a different complement.","D":"**So that** introduces a finite purpose clause whose subject is you."}}},{"id":"e0478732-88b7-5b9a-abd8-786e7adb1ca8","topicSlug":"linking-clauses","level":"B1","prompt":"Use the time preposition before an -ing noun phrase: “The error occurred during the process of ____ the visitor guide.”","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"preparing"},{"id":"C","text":"prepare"},{"id":"D","text":"to prepare"}],"answerId":"B","hint":"The preposition **of** needs a noun-like complement: use the **-ing form**.","explanation":"After preposition **of**, use **preparing** to name the process.","keywords":["during-while"],"skill":"during-while","contextKey":"linking-clauses-1","fingerprint":"3441488ccbab8c91978d69d5bbf998a717fe17d32910e2723872525a3f95ae4e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The preposition **of** needs a noun-like complement: use the **-ing form**.","After preposition **of**, use **preparing** to name the process.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A past form does not name the process after of.","B":"After preposition **of**, use **preparing** to name the process.","C":"A base verb does not supply the noun-like complement after of.","D":"A to-infinitive cannot directly follow of in this pattern."}}},{"id":"68ec06ca-7794-5396-a018-6d1fb596ca4c","topicSlug":"linking-clauses","level":"B1","prompt":"“We were tired ____ we had restored the old portrait all morning.”","choices":[{"id":"A","text":"because of"},{"id":"B","text":"despite"},{"id":"C","text":"during"},{"id":"D","text":"because"}],"answerId":"D","hint":"The reason has its own **subject and verb**.","explanation":"**Because** introduces the reason as a finite clause: we had ... .","keywords":["because-finite-clause"],"skill":"because-finite-clause","contextKey":"linking-clauses-2","fingerprint":"78c70c4dc089d7467cdbc2edefa96c21655e889f95d6c96a2c15d46439163965","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reason has its own **subject and verb**.","**Because** introduces the reason as a finite clause: we had ... .","Choose **because**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Because of normally takes a noun phrase or -ing expression, not this finite clause.","B":"Despite would need a noun phrase and would express contrast, not the stated reason.","C":"During takes a noun phrase, not a finite clause.","D":"**Because** introduces the reason as a finite clause: we had ... ."}}},{"id":"0868435f-110b-5bcc-a9a1-5db81059f8a7","topicSlug":"linking-clauses","level":"B1","prompt":"“We could not restore the old portrait ____ the power cut.”","choices":[{"id":"A","text":"although"},{"id":"B","text":"while"},{"id":"C","text":"because of"},{"id":"D","text":"because"}],"answerId":"C","hint":"The reason is a **noun phrase**, so choose because of.","explanation":"The reason is a noun phrase, **the power cut**, so use **because of**.","keywords":["because-of-noun"],"skill":"because-of-noun","contextKey":"linking-clauses-2","fingerprint":"05ccada6978bbdb8215d82966b84edd85e23fc0c88142d43c6013bc391d12a24","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reason is a **noun phrase**, so choose because of.","The reason is a noun phrase, **the power cut**, so use **because of**.","Choose **because of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Although normally introduces a finite clause and gives contrast rather than this reason.","B":"While would normally introduce a clause, not this bare reason phrase.","C":"The reason is a noun phrase, **the power cut**, so use **because of**.","D":"Because requires a finite reason clause rather than this noun phrase alone."}}},{"id":"79e75177-d33f-5f19-a13b-e66279114fbe","topicSlug":"linking-clauses","level":"B1","prompt":"Express purpose with a different subject: “I brought the instructions ____ you could restore the old portrait.”","choices":[{"id":"A","text":"despite"},{"id":"B","text":"so that"},{"id":"C","text":"in order to"},{"id":"D","text":"because of"}],"answerId":"B","hint":"The purpose clause has its own subject **you** and modal **could**.","explanation":"**So that** introduces a finite purpose clause whose subject is you.","keywords":["purpose-so-that"],"skill":"purpose-so-that","contextKey":"linking-clauses-2","fingerprint":"aeb8b0248925df463d9425287ce0d26f79a29c7a742207e817a13e936af8ad11","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The purpose clause has its own subject **you** and modal **could**.","**So that** introduces a finite purpose clause whose subject is you.","Choose **so that**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Despite both changes the relation and requires a different complement.","B":"**So that** introduces a finite purpose clause whose subject is you.","C":"In order to needs a base verb immediately, not you could.","D":"Because of cannot introduce this finite purpose clause."}}},{"id":"6d9afaac-359f-51fa-a806-82b7b2175c40","topicSlug":"linking-clauses","level":"B1","prompt":"Use the time preposition before an -ing noun phrase: “The error occurred during the process of ____ the old portrait.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"restor